def specs():
    domains = {}
    for line in DOMAINS.splitlines():
        key, inputs, measures, related = line.split('|')
        domains[key] = dict(domain=key, required_inputs=inputs.split(', '), measures=measures.split(', '), related_domains=related.split(','), workflows=[])
    for line in WORKFLOWS.splitlines():
        domain, slug, title, query, steps, output = line.split('|')
        domains[domain]['workflows'].append(dict(id=domain+'.'+slug,title=title,query=query,steps=steps.split('~'),deliverable=output))
    return domains
